d not record that.", "anything_else": "Is there anything else I can help you with?", "wrap_change": "An arrangement already recorded cannot be changed on this call.", "and": " and ", "after_recorded": ""\x7d, "multi": true, "notes": true, "note_reasons": \x7b"refused": "refused", "hardship": "hardship", "dispute": "dispute", "paid": "paid", "service_error": "service_error"\x7d, "fin_keys": \x7b"promise": "promise", "paid": "paid", "default": "secondlook", "refused": "secondlook", "hardship": "hardship", "dispute": "dispute", "service_error": "sysf"\x7d, "asides": \x7b"robot": \x7b"when": "asks whether they are talking to a robot, a machine or an AI", "say": "Yes, I am an automated assistant."\x7d, "scam": \x7b"when": "asks whether this call is a scam or genuine", "say": "You are free to hang up and call us on the number on the Corran Bay website."\x7d\x7d, "weekday_rule": "this_week", "fail_max": 2, "defer_notes": true, "max_checks": 8, "human_limit": 2, "notalk_limit": 2, "wrap_turns": 2, "closed_day_move": "after", "ordinals": ["first", "second", "third"], "clear_enums": \x7b"stance": "other", "offer_kind": "none", "offer_for": "none", "topic": "none", "confirm": "other", "hs_answer": "none", "wrap": "other", "aside": "none", "offer_ref": "none"\x7d, "clear_values": \x7b"offer_date": "1900-01-01", "offer_amount": "0", "offer_when": "", "per_product": ""\x7d, "outcome_var": "outcome", "reason_var": "reason", "promise_outcome": "promise", "now_var": "now", "after_recorded": false, "vague_again": "deadline", "above_full": "agree", "promise_reasons": \x7b"full": "FULLPTP", "partial": "PARTPTP"\x7d\x7d')
    def g(V, k, d=''):
        v = V.get(k)
        if v is None:
            return d
        s = str(v)
        return d if s.lower() in ('none', 'null') and d == '' else s
    def num(x, d=None):
        try:
            s = str(x).replace(',', '').strip()
            if not s or s.lower() in ('none', 'null', 'nan'):
                return d
            m = re.search(r'-?\d+(\.\d+)?', s)
            return float(m.group(0)) if m else d
        except Exception:
            return d
    def pdate(x):
        s = str(x or '').strip()
        m = re.search(r'(\d{4})-(\d{1,2})-(\d{1,2})', s)
        if not m or int(m.group(1)) <= 1900:   # 1900-01-01 is the 'cleared' sentinel (schema-valid date)
            return None
        try:
            return datetime.date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
        except Exception:
            return None
    def T(key, **kw):
        s = str(P['texts'].get(key) or '')
        for k, v in kw.items():
            s = s.replace('[' + k + ']', str(v))
        return s
    def join(parts):
        return ' '.join([str(x).strip() for x in parts if str(x or '').strip()])
    def pids(V):
        return [x for x in g(V, 'pids_csv').split(',') if x]
    def pg(V, pid, k, d=''):
        return g(V, k + '_' + pid, d)
    def pset(V, pid, k, v):
        V[k + '_' + pid] = str(v)
    def today_of(V):
        d = pdate(g(V, 'today_iso')) or pdate(g(V, P['now_var']))
        return d or datetime.date(2000, 1, 1)
    def when(V, d):
        if d == today_of(V):
            return T('today_word')
        # optional ('' = off): 'tomorrow, Thursday 15 October' lets a customer who said 'tomorrow' recognise the day (a
        # simulated customer that does not know the call's date said 'not correct' to the bare date, EXT-A-11)
        if T('tomorrow_when') and d == today_of(V) + datetime.timedelta(days=1):
            return T('tomorrow_when', date=txt_short(d))
        return T('on_date', date=txt_short(d))
    def dtext(V, d):
        return T('today_word') if d == today_of(V) else txt_short(d)
    def full_of(V, pid):
        return num(pg(V, pid, 'full'), 0.0) or 0.0
    def floor_of(V, pid):
        f = num(pg(V, pid, 'floor'))
        return full_of(V, pid) if f is None or f <= 0 else f
    def deadline_of(V, pid):
        return pdate(pg(V, pid, 'deadline')) or today_of(V)
    def state(V, pid):
        return pg(V, pid, 'state', 'open')
